<form class="card mb-4 grid gap-3 p-4 sm:grid-cols-2 lg:grid-cols-5" method="get"><div><label class="form-label" for="status">Status</label><select class="form-control" id="status" name="status"><option value="">All</option><?php foreach(['queued','scheduled','sending','sent','delivered','failed','refunded'] as $s): ?><option value="<?= $s ?>" <?= service('request')->getGet('status')===$s?'selected':'' ?>><?= $s ?></option><?php endforeach ?></select></div><div><label class="form-label" for="type">Type</label><input class="form-control" id="type" name="type" value="<?= esc((string)service('request')->getGet('type')) ?>"></div><div><label class="form-label" for="from">From</label><input class="form-control" id="from" type="date" name="from" value="<?= esc((string)service('request')->getGet('from')) ?>"></div><div><label class="form-label" for="to">To</label><input class="form-control" id="to" type="date" name="to" value="<?= esc((string)service('request')->getGet('to')) ?>"></div><div class="flex items-end"><button class="btn-primary w-full">Filter</button></div></form>
<div class="card overflow-x-auto"><table class="w-full min-w-[850px] text-left text-sm"><thead class="bg-gray-50"><tr><?php foreach(['Date','Batch','Recipient','Child','Message','Status','Provider / action'] as $h): ?><th class="p-3"><?= esc($h) ?></th><?php endforeach ?></tr></thead><tbody><?php foreach($rows as $r): ?><tr class="border-t"><td class="p-3"><?= esc($r['created_at']) ?></td><td class="p-3"><?= esc($r['batch_title']??'—') ?></td><td class="p-3"><?= esc($r['recipient_number']) ?></td><td class="p-3"><?= esc(trim(($r['first_name']??'').' '.($r['last_name']??''))?:'—') ?></td><td class="max-w-xs truncate p-3" title="<?= esc($r['body']) ?>"><?= esc($r['body']) ?></td><td class="p-3"><?= view('components/badge',['label'=>ucfirst($r['status']),'tone'=>$r['status']==='sent'||$r['status']==='delivered'?'success':($r['status']==='failed'?'danger':'warning')]) ?></td><td class="p-3"><?= esc($r['provider_status']??$r['error_message']??'—') ?><?php if($r['status']==='failed'): ?><form method="post" action="<?= site_url('sms/messages/'.$r['id'].'/retry') ?>" class="mt-2"><?= csrf_field() ?><button class="text-blue-700 underline">Retry</button></form><?php endif ?></td></tr><?php endforeach ?><?php if(!$rows): ?><tr><td colspan="7" class="p-6 text-center text-gray-500">No messages found.</td></tr><?php endif ?></tbody></table></div><div class="mt-4"><?= $pager->links() ?></div>
